-- Synthetic all-table projection equality, including precision fixture / JSON spelling.
DO $$ DECLARE t text; mismatch boolean; BEGIN
 FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='stock_operational' AND tablename NOT IN ('environment','commands','side_effects','revision') LOOP
  EXECUTE format('SELECT EXISTS(SELECT FROM stock_operational.%I r WHERE business_cells IS DISTINCT FROM stock_operational.project_%I(r))',t,t) INTO mismatch;
  IF mismatch THEN RAISE EXCEPTION 'Projection mismatch in %',t; END IF;
 END LOOP;
END $$;
INSERT INTO stock_operational.orders(id,remark,"totalPrice") VALUES ('NC_TEST','before',12.3400);
UPDATE stock_operational.orders SET remark='after release' WHERE id='NC_TEST';
SELECT 1 / ((SELECT business_cells->>4='after release' AND revision=2 FROM stock_operational.orders WHERE id='NC_TEST'))::int;
DO $$ BEGIN
 BEGIN UPDATE stock_operational.orders SET business_cells='["NC_TEST","stale"]' WHERE id='NC_TEST'; RAISE EXCEPTION 'Legacy write accepted'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='Legacy write accepted' THEN RAISE; END IF; END;
 BEGIN UPDATE stock_operational.orders SET id='changed' WHERE id='NC_TEST'; RAISE EXCEPTION 'Identity change accepted'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='Identity change accepted' THEN RAISE; END IF; END;
 BEGIN UPDATE stock_operational.orders SET row_order=999999 WHERE id='NC_TEST'; RAISE EXCEPTION 'Reorder accepted'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='Reorder accepted' THEN RAISE; END IF; END;
END $$;
